FishEyeScrollViewItem = class("FishEyeScrollViewItem")

function FishEyeScrollViewItem:ctor()
end

function FishEyeScrollViewItem:InitPanel(gameObject)
    self.gameObject = gameObject;
    self.transform = gameObject.transform;
    self:FindComponent(self.transform);
    self.callback = nil;
    self.heroId = 0;
    EventDelegate.Add(self.trigger.onClick,EventDelegate.Callback(function() self:ItemClick() end));
end

function FishEyeScrollViewItem:ItemClick()
    if self.callback ~= nil then
        self.callback(self);
    end
end

function FishEyeScrollViewItem:FindComponent(transform)
    local tTransform = transform;
    self.trigger = Util.FindChildEx(tTransform,""):GetComponent("UIEventTrigger");
    self.tex_HeroHead = Util.FindChildEx(tTransform,"tex_HeroHead"):GetComponent("UITexture");
    self.lab_HeroName = Util.FindChildEx(tTransform,"lab_HeroName"):GetComponent("UILabel");
end

function FishEyeScrollViewItem:SetItem(heroId, callback)
    self.callback = callback;
    self.heroId = heroId;

    TextureSystem.Instance:LoadTextureX(string.format("HeroBody_%d", heroId),TextureSystem.TextureGroup.MyHero,function(tex_2d)
        self.tex_HeroHead.mainTexture  = tex_2d;
    end)
    self.lab_HeroName.text = TextSystem.GetText(string.format("hero_card_name_%d", heroId));
end